<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{client,requireData}from'../../shared/api/client';import type{components}from'../../shared/api/schema.gen';const props=defineProps<{modelValue:string,capability?:string}>();const emit=defineEmits<{'update:modelValue':[value:string]}>();const values=ref<components['schemas']['ModelInfo'][]>([]);const filtered=computed(()=>values.value.filter(value=>!props.capability||value.capabilities.includes(props.capability)));onMounted(async()=>{values.value=requireData(await client.GET('/api/admin/models/catalog'))})</script>
<template><select :value="modelValue" class="nw-input" @change="emit('update:modelValue',($event.target as HTMLSelectElement).value)"><option value="">未选择</option><option v-for="value in filtered" :key="`${value.channel}:${value.id}`" :value="`${value.channel}:${value.id}`">{{ value.name }} · {{ value.channel }}</option></select></template>
